"""CCAO-F part B1: flashcards and questions for Domains 4-7.

Domain 4 Workflow Integration and Solution Design (16%), Domain 5 Configuration and
Knowledge Management (12%), Domain 6 Governance, Risk, and Responsible Use (15%) and
Domain 7 Troubleshooting and Optimization (10%) of the Claude Certified Associate -
Foundations exam guide (version 1.0, effective July 2026).

Product and policy facts were checked in October 2026 against the Claude Help Center
(Projects, retrieval for Projects, Skills, plugins, connectors and Google Workspace
connectors, enterprise search, artifacts and sharing, file creation, file uploads,
memory, usage-limit and error-message guidance), the Anthropic Privacy Center
(consumer and commercial data use, retention, DPA, BAA, certifications), the Anthropic
Usage Policy (high-risk use case requirements and disclosure), the Help Center article
on how Claude marks AI-generated content, the Claude prompting best-practices docs, and
Anthropic's AI Fluency framework (Delegation, Description, Discernment, Diligence; the
automation, augmentation and agency modes). Governance items are phrased as principles
and avoid dated figures so they stay true as the products change.
Part B2 (data/ccao_b2.py) holds the lessons, games, case studies and cheat sheet that
build on these ids (flashcards f1001.., questions q1001.., msq1001.., tf1001..).
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


